create table if not exists public.youtube_content (
  id uuid primary key default gen_random_uuid(),
  song_title text not null,
  video_link text not null default '',
  tags text not null default '' check (char_length(tags) <= 500),
  updated_at timestamptz not null default now()
);
create index if not exists youtube_content_song_title_idx on public.youtube_content (song_title);
alter table public.youtube_content enable row level security;
revoke all on public.youtube_content from anon, authenticated;
grant all on public.youtube_content to service_role;

on conflict do nothing;
